    """Match debt-note tables that state carrying value, face value, or net carrying amount of long-term debt."""
    try:
        hits: list[dict] = []
        for span in doc.get("texts", []):
            if span.get("label") != "table":
                continue
            text = " ".join((span.get("text") or "").split()).lower()
            path = " ".join((((span.get("structure") or {}).get("path_text")) or "").split()).lower()
            if "debt" not in path:
                continue
            if (
                "carrying value of long-term debt" in text
                or "face value of long-term debt" in text
                or "total net carrying amount" in text
                or "long-term debt, excluding current portion" in text
                or "debt, non-current" in text
            ):
                hits.append(span)
        return hits
    except Exception:
        return []

def rule_financial_statement_balance_sheet_debt_tables(doc: dict) -> list[dict]:
    """Match financial-statement balance-sheet tables with long-term debt rows, excluding Item 16 summary tables."""
    try:
        hits: list[dict] = []
        for span in doc.get("texts", []):
            if span.get("label") != "table":
                continue
            text = " ".join((span.get("text") or "").split()).lower()
            path = " ".join((((span.get("structure") or {}).get("path_text")) or "").split()).lower()
            if "item 16" in path or "item 7a" in path or "market risk" in path:
                continue
            is_balance_sheet = (
                "balance sheet" in path
                or "balance sheets" in path
                or "financial position" in path
                or "condensed consolidated financial statements" in path
                or (
                    ("financial statements" in path or "financial information" in path)
                    and "assets" in text
                    and "liabilities" in text
                )
            )
            if not is_balance_sheet:
                continue
            if (
                "long-term debt" in text
                or "debt, non-current" in text
                or "long-term obligations" in text
                or ("long-term liabilities" in text and "debt" in text)
                or ("non-current liabilities" in text and "long-term debt" in text)
            ):
                hits.append(span)
        return hits
    except Exception:
        return []

def rule_8k_cover_current_report_context(doc: dict) -> list[dict]:
    """Match early Form 8-K cover spans that establish the filing is a current report with no year-end debt table."""
    try:
        hits: list[dict] = []
        for span in doc.get("texts", []):
            page_no = span.get("page_no") or 99
            if page_no > 2:
                continue
            if span.get("label") not in {"text", "section_header"}:
                continue
            text = " ".join((span.get("text") or "").split()).lower()
            if len(text) > 140:
                continue
            if (
                "form 8-k" in text
                or "current report" in text
                or text.startswith("item 8.01")
                or text.startswith("item 5.07")
                or text.startswith("item 9.01")
            ):
                hits.append(span)
        return hits
    except Exception:
        return []

def rule_mda_or_market_risk_debt_summary_tables(doc: dict) -> list[dict]:
    """Match MD&A or market-risk tables summarizing debt, net debt, or long-term debt totals."""
    try:
        hits: list[dict] = []
        for span in doc.get("texts", []):
